function safeUrl(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function safeMapsUrl(value){try{const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password)return '';const h=u.hostname,p=u.pathname;const valid=h==='maps.app.goo.gl'&&p.length>1||h==='goo.gl'&&/^\/maps\/.+/.test(p)||['maps.google.com','maps.google.co.id'].includes(h)||['google.com','www.google.com','google.co.id','www.google.co.id'].includes(h)&&/^\/maps(?:\/|$)/.test(p);return valid?u.href:''}catch{return ''}}
